1	import { useState } from "react";
2	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
3	import { ApiError, api } from "../api/client";
4	import type { Assignment, MissionDetail } from "../api/types";
5	import { useAuth } from "../auth/AuthContext";
6	import { MissionStatusBadge } from "../components/StatusBadge";
7	import { ErrorBanner } from "../components/ErrorBanner";
8	import { Spinner } from "../components/Spinner";
9	import { FulfillmentBar } from "../components/FulfillmentBar";
10	import { formatDateRange, initials } from "../lib/format";
11	
12	function errorMessage(error: unknown, fallback: string): string {
13	  return error instanceof ApiError ? error.message : fallback;
14	}
15	
16	interface ProposeVars {
17	  requirementId: number;
18	  crewId: number;
19	}
20	
21	export function MissionDetailScreen({ missionId, onBack }: { missionId: number; onBack: () => void }) {
22	  const { user } = useAuth();
23	  const queryClient = useQueryClient();
24	  const [hasRunMatcher, setHasRunMatcher] = useState(false);
25	  const [showRejectForm, setShowRejectForm] = useState(false);
26	  const [rejectReason, setRejectReason] = useState("");
27	
28	  const missionQuery = useQuery({
29	    queryKey: ["mission", missionId],
30	    queryFn: () => api.mission.get(missionId),
31	  });
32	
33	  const assignmentsQuery = useQuery({
34	    queryKey: ["assignments"],
35	    queryFn: api.assignment.list,
36	  });
37	
38	  const matchQuery = useQuery({
39	    queryKey: ["match", missionId],
40	    queryFn: () => api.match.run(missionId),
41	    enabled: hasRunMatcher,
42	  });
43	
44	  const approveMutation = useMutation({
45	    mutationFn: () => api.mission.approve(missionId),
46	    onMutate: async () => {
47	      await queryClient.cancelQueries({ queryKey: ["mission", missionId] });
48	      const previous = queryClient.getQueryData<MissionDetail>(["mission", missionId]);
49	      if (previous) queryClient.setQueryData<MissionDetail>(["mission", missionId], { ...previous, status: "approved" });
50	      return { previous };
51	    },
52	    onError: (_err, _vars, context) => {
53	      if (context?.previous) queryClient.setQueryData(["mission", missionId], context.previous);
54	    },
55	    onSettled: () => queryClient.invalidateQueries({ queryKey: ["mission", missionId] }),
56	  });
57	
58	  const rejectMutation = useMutation({
59	    mutationFn: (reason: string) => api.mission.reject(missionId, reason),
60	    onMutate: async (reason) => {
61	      await queryClient.cancelQueries({ queryKey: ["mission", missionId] });
62	      const previous = queryClient.getQueryData<MissionDetail>(["mission", missionId]);
63	      if (previous) queryClient.setQueryData<MissionDetail>(["mission", missionId], { ...previous, status: "draft" });
64	      return { previous, reason };
65	    },
66	    onSuccess: () => {
67	      setShowRejectForm(false);
68	      setRejectReason("");
69	    },
70	    onError: (_err, _vars, context) => {
71	      if (context?.previous) queryClient.setQueryData(["mission", missionId], context.previous);
72	    },
73	    onSettled: () => queryClient.invalidateQueries({ queryKey: ["mission", missionId] }),
74	  });
75	
76	  const proposeMutation = useMutation({
77	    mutationFn: (vars: ProposeVars) => api.assignment.propose(missionId, vars.requirementId, vars.crewId),
78	    onMutate: async (vars) => {
79	      await queryClient.cancelQueries({ queryKey: ["assignments"] });
80	      const previous = queryClient.getQueryData<Assignment[]>(["assignments"]);
81	      const optimistic: Assignment = {
82	        // Negative id marks this row as "not yet confirmed by the server" —
83	        // the UI uses it to show the optimistic-update note (mockup: "shown
84	        // instantly on click"). Replaced by the real row once settled.
85	        id: -Date.now(),
86	        mission_id: missionId,
87	        requirement_id: vars.requirementId,
88	        crew_id: vars.crewId,
89	        proposed_by: user?.id ?? 0,
90	        status: "proposed",
91	        proposed_at: new Date().toISOString(),
92	        responded_at: null,
93	      };
94	      queryClient.setQueryData<Assignment[]>(["assignments"], (old) => [...(old ?? []), optimistic]);
95	      return { previous };
96	    },
97	    onError: (_err, _vars, context) => {
98	      if (context?.previous) queryClient.setQueryData(["assignments"], context.previous);
99	    },
100	    onSettled: () => queryClient.invalidateQueries({ queryKey: ["assignments"] }),
101	  });
102	
103	  if (missionQuery.isPending) {
104	    return (
105	      <div className="flex flex-1 items-center justify-center px-10 py-8">
106	        <Spinner className="h-6 w-6 text-text-3" />
107	      </div>
108	    );
109	  }
110	
111	  if (missionQuery.isError) {
112	    return (
113	      <div className="flex flex-1 flex-col gap-4 px-10 py-8">
114	        <BackLink onBack={onBack} />
115	        <ErrorBanner message={errorMessage(missionQuery.error, "Couldn't load this mission.")} onRetry={() => missionQuery.refetch()} />
116	      </div>
117	    );
118	  }
119	
120	  const mission = missionQuery.data;
121	  const assignments = assignmentsQuery.data ?? [];
122	  const canReview = user?.role === "director" && mission.status === "pending_approval";
123	  const isOwnMission = mission.created_by === user?.id;
124	
125	  return (
126	    <div className="flex flex-1 flex-col gap-5 overflow-y-auto px-10 py-7">
127	      <BackLink onBack={onBack} />
128	
129	      <div>
130	        <div className="flex items-center gap-3">
131	          <div className="text-2xl font-bold">{mission.name}</div>
132	          <MissionStatusBadge status={mission.status} />
133	        </div>
134	        <div className="mt-1.5 text-[13px] text-text-2">{formatDateRange(mission.start_date, mission.end_date)}</div>
135	        <p className="mt-2 max-w-2xl text-sm text-text-2">{mission.description}</p>
136	      </div>
137	
138	      <div className="flex items-start gap-7">
139	        {/* Left column */}
140	        <div className="flex min-w-0 flex-1 flex-col gap-5">
141	          <div className="rounded-[10px] border border-border bg-surface p-5">
142	            <div className="mb-4 text-[15px] font-bold">Requirements</div>
143	            {mission.requirements.length === 0 ? (
144	              <div className="text-sm text-text-3">No requirements added yet.</div>
145	            ) : (
146	              <div className="flex flex-col gap-3.5">
147	                {mission.requirements.map((req) => (
148	                  <div key={req.id} className="flex items-center justify-between rounded-lg bg-surface-2 px-3.5 py-3">
149	                    <div>
150	                      <div className="text-[13.5px] font-semibold">{req.skill_name}</div>
151	                      <div className="text-xs text-text-3">
152	                        Proficiency ≥ {req.min_proficiency} · needs {req.headcount}
153	                      </div>
154	                    </div>
155	                    <FulfillmentBar confirmed={req.confirmed} headcount={req.headcount} />
156	                  </div>
157	                ))}
158	              </div>
159	            )}
160	          </div>
161	
162	          {(user?.role === "director" || user?.role === "mission_lead") && (
163	            <div className="rounded-[10px] border border-border bg-surface p-5">
164	              <div className="mb-1 flex items-center justify-between">
165	                <div className="text-[15px] font-bold">Matcher</div>
166	                {hasRunMatcher && (
167	                  <button
168	                    type="button"
169	                    onClick={() => matchQuery.refetch()}
170	                    disabled={matchQuery.isFetching}
171	                    className="flex items-center gap-1.5 text-[12.5px] text-accent hover:text-accent-dark disabled:opacity-60"
172	                  >
173	                    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
174	                      <path d="M21 12a9 9 0 1 1-3-6.7M21 3v6h-6" />
175	                    </svg>
176	                    Re-run matcher
177	                  </button>
178	                )}
179	              </div>
180	              <div className="mb-4 text-xs text-text-3">
181	                Ranked by proficiency surplus (50%) · workload (30%) · availability margin (20%). Every eligible crew
182	                member is shown, not just the top few.
183	              </div>
184	
185	              {!hasRunMatcher && (
186	                <button
187	                  type="button"
188	                  onClick={() => setHasRunMatcher(true)}
189	                  className="rounded-md bg-accent px-4 py-2 text-[13px] font-semibold text-white"
190	                >
191	                  Run matcher
192	                </button>
193	              )}
194	
195	              {hasRunMatcher && matchQuery.isPending && (
196	                <div className="flex items-center gap-2 text-sm text-text-3">
197	                  <Spinner /> Running matcher…
198	                </div>
199	              )}
200	
201	              {hasRunMatcher && matchQuery.isError && (
202	                <ErrorBanner message={errorMessage(matchQuery.error, "Couldn't run the matcher.")} onRetry={() => matchQuery.refetch()} />
203	              )}
204	
205	              {hasRunMatcher && matchQuery.isSuccess && (
206	                <div className="flex flex-col gap-6">
207	                  {matchQuery.data.map((requirementMatch) => {
208	                    const requirement = mission.requirements.find((r) => r.id === requirementMatch.requirement_id);
209	                    return (
210	                      <div key={requirementMatch.requirement_id}>
211	                        <div className="mb-2.5 text-[13px] font-semibold text-text-2">
212	                          {requirement?.skill_name ?? `Requirement #${requirementMatch.requirement_id}`}
213	                        </div>
214	                        {requirementMatch.candidates.length === 0 ? (
215	                          <div className="text-sm text-text-3">No eligible candidates for this requirement.</div>
216	                        ) : (
217	                          <div className="flex flex-col gap-2.5">
218	                            {requirementMatch.candidates.map((candidate) => (
219	                              <CandidateRow
220	                                key={candidate.crew_id}
221	                                candidate={candidate}
222	                                requirementId={requirementMatch.requirement_id}
223	                                assignments={assignments}
224	                                proposeMutation={proposeMutation}
225	                              />
226	                            ))}
227	                          </div>
228	                        )}
229	                      </div>
230	                    );
231	                  })}
232	                </div>
233	              )}
234	            </div>
235	          )}
236	        </div>
237	
238	        {/* Right column */}
239	        <div className="flex w-72 flex-none flex-col gap-4.5">
240	          {canReview && (
241	            <div className="rounded-[10px] border border-pending bg-surface p-5">
242	              <div className="mb-1.5 text-sm font-bold">Awaiting your review</div>
243	              {isOwnMission ? (
244	                <p className="text-xs leading-relaxed text-text-2">
245	                  You created this mission, so you're not eligible to approve or reject it — another Director must
246	                  review it.
247	                </p>
248	              ) : (
249	                <>
250	                  <p className="mb-4 text-xs leading-relaxed text-text-2">
251	                    This mission is pending your approval.
252	                  </p>
253	                  <div className="flex flex-col gap-2.5">
254	                    <button
255	                      type="button"
256	                      onClick={() => approveMutation.mutate()}
257	                      disabled={approveMutation.isPending}
258	                      className="flex w-full items-center justify-center gap-2 rounded-md bg-approved px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-70"
259	                    >
260	                      {approveMutation.isPending && <Spinner />}
261	                      Approve
262	                    </button>
263	                    {!showRejectForm && (
264	                      <button
265	                        type="button"
266	                        onClick={() => setShowRejectForm(true)}
267	                        className="w-full rounded-md border border-danger-border bg-surface px-4 py-2.5 text-sm font-semibold text-danger"
268	                      >
269	                        Reject…
270	                      </button>
271	                    )}
272	                    {showRejectForm && (
273	                      <div className="flex flex-col gap-2">
274	                        <label htmlFor="reject-reason" className="text-xs font-semibold text-text-2">
275	                          Reason for rejecting
276	                        </label>
277	                        <textarea
278	                          id="reject-reason"
279	                          value={rejectReason}
280	                          onChange={(e) => setRejectReason(e.target.value)}
281	                          rows={3}
282	                          className="w-full rounded-md border border-border bg-surface p-2 text-xs focus:border-accent focus:outline-none"
283	                          placeholder="Why is this mission being sent back to draft?"
284	                        />
285	                        <div className="flex gap-2">
286	                          <button
287	                            type="button"
288	                            onClick={() => rejectMutation.mutate(rejectReason)}
289	                            disabled={rejectMutation.isPending || rejectReason.trim().length === 0}
290	                            className="flex flex-1 items-center justify-center gap-2 rounded-md bg-danger px-3 py-2 text-xs font-semibold text-white disabled:cursor-not-allowed disabled:opacity-60"
291	                          >
292	                            {rejectMutation.isPending && <Spinner />}
293	                            Confirm reject
294	                          </button>
295	                          <button
296	                            type="button"
297	                            onClick={() => {
298	                              setShowRejectForm(false);
299	                              setRejectReason("");
300	                            }}
301	                            className="rounded-md border border-border px-3 py-2 text-xs font-semibold text-text-2"
302	                          >
303	                            Cancel
304	                          </button>
305	                        </div>
306	                      </div>
307	                    )}
308	                  </div>
309	                </>
310	              )}
311	              {approveMutation.isError && (
312	                <div className="mt-3">
313	                  <ErrorBanner message={errorMessage(approveMutation.error, "Couldn't approve this mission.")} onRetry={() => approveMutation.mutate()} />
314	                </div>
315	              )}
316	              {rejectMutation.isError && (
317	                <div className="mt-3">
318	                  <ErrorBanner message={errorMessage(rejectMutation.error, "Couldn't reject this mission.")} />
319	                </div>
320	              )}
321	            </div>
322	          )}
323	
324	          <div className="rounded-[10px] border border-border bg-surface p-5">
325	            <div className="mb-3.5 text-[13px] font-bold">Fulfillment</div>
326	            {mission.requirements.length === 0 ? (
327	              <div className="text-xs text-text-3">No requirements yet.</div>
328	            ) : (
329	              <div className="flex flex-col gap-3">
330	                {mission.requirements.map((req) => {
331	                  const pct = req.headcount > 0 ? Math.min(100, Math.round((req.confirmed / req.headcount) * 100)) : 0;
332	                  return (
333	                    <div key={req.id}>
334	                      <div className="mb-1 flex justify-between text-xs">
335	                        <span>{req.skill_name}</span>
336	                        <span className="font-mono text-text-2">
337	                          {req.confirmed}/{req.headcount}
338	                        </span>
339	                      </div>
340	                      <div className="h-1 rounded-full bg-border">
341	                        <div
342	                          className="h-full rounded-full"
343	                          style={{
344	                            width: `${pct}%`,
345	                            backgroundColor: req.confirmed >= req.headcount ? "var(--color-approved)" : "var(--color-pending)",
346	                          }}
347	                        />
348	                      </div>
349	                    </div>
350	                  );
351	                })}
352	              </div>
353	            )}
354	          </div>
355	        </div>
356	      </div>
357	    </div>
358	  );
359	}
360	
361	function BackLink({ onBack }: { onBack: () => void }) {
362	  return (
363	    <button type="button" onClick={onBack} className="flex w-fit items-center gap-1.5 text-xs text-text-2 hover:text-accent">
364	      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
365	        <path d="M15 6l-6 6 6 6" />
366	      </svg>
367	      All missions
368	    </button>
369	  );
370	}
371	
372	function CandidateRow({
373	  candidate,
374	  requirementId,
375	  assignments,
376	  proposeMutation,
377	}: {
378	  candidate: { crew_id: number; crew_name: string; score: number; breakdown: string };
379	  requirementId: number;
380	  assignments: Assignment[];
381	  proposeMutation: ReturnType<typeof useMutation<Assignment, Error, ProposeVars>>;
382	}) {
383	  const existing = assignments.find(
384	    (a) => a.requirement_id === requirementId && a.crew_id === candidate.crew_id && a.status !== "declined",
385	  );
386	  const isThisRow =
387	    proposeMutation.variables?.requirementId === requirementId && proposeMutation.variables?.crewId === candidate.crew_id;
388	  const isPending = proposeMutation.isPending && isThisRow;
389	  const isError = proposeMutation.isError && isThisRow;
390	
391	  return (
392	    <div className="flex flex-col gap-2.5 rounded-lg border border-border p-3.5">
393	      <div className={`flex items-center gap-3.5 ${isPending ? "opacity-70" : ""}`}>
394	        <div className="flex h-8 w-8 flex-none items-center justify-center rounded-full bg-surface-2 text-xs font-bold text-text-2">
395	          {initials(candidate.crew_name)}
396	        </div>
397	        <div className="flex-1">
398	          <div className="text-[13.5px] font-semibold">
399	            {candidate.crew_name} <span className="font-mono text-xs font-medium text-text-2">· score {candidate.score.toFixed(2)}</span>
400	          </div>
401	          <div className="mt-0.5 font-mono text-[11.5px] text-text-3">{candidate.breakdown}</div>
402	        </div>
403	
404	        {isPending && (
405	          <div className="flex items-center gap-1.5 text-xs font-semibold text-text-2">
406	            <Spinner /> Proposing…
407	          </div>
408	        )}
409	
410	        {!isPending && existing?.status === "confirmed" && (
411	          <div className="flex items-center gap-1.5 rounded-full bg-approved-bg px-3 py-1.5 text-xs font-semibold text-approved">
412	            Confirmed
413	          </div>
414	        )}
415	
416	        {!isPending && existing?.status === "proposed" && (
417	          <div className="flex items-center gap-1.5 rounded-full border border-dashed border-pending px-3 py-1.5 text-xs font-semibold text-pending">
418	            <svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor" stroke="none">
419	              <circle cx="12" cy="12" r="6" />
420	            </svg>
421	            Pending confirmation
422	          </div>
423	        )}
424	
425	        {!isPending && !existing && (
426	          <button
427	            type="button"
428	            onClick={() => proposeMutation.mutate({ requirementId, crewId: candidate.crew_id })}
429	            className="rounded-md bg-accent px-3.5 py-1.5 text-xs font-semibold text-white"
430	          >
431	            Propose
432	          </button>
433	        )}
434	      </div>
435	
436	      {!isPending && existing?.status === "proposed" && existing.id < 0 && (
437	        <div className="ml-[46px] flex items-center gap-1.5 text-[11px] text-text-3">
438	          <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
439	            <path d="M21 12a9 9 0 1 1-3-6.7" />
440	          </svg>
441	          Shown instantly on click — confirming with the server in the background
442	        </div>
443	      )}
444	
445	      {isError && (
446	        <div className="ml-[46px]">
447	          <ErrorBanner
448	            message={`Couldn't propose — ${errorMessage(proposeMutation.error, "something went wrong.")}`}
449	            onRetry={() => proposeMutation.mutate({ requirementId, crewId: candidate.crew_id })}
450	          />
451	        </div>
452	      )}
453	    </div>
454	  );
455	}
